return "<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<table name=\"general\">\n<key>id</key>\n<r><f n=\"tactic_id\">1302</f> <f n=\"name\">Chu Du</f> <f n=\"sp_i\">Xích Bích Nghiệp Viêm, tấn công 2 dãy địch, kèm buff Hỗn Loạn, được thả 2 lần; cùng Lục Tốn chiến pháp hình thành buff hợp kích</f> <f n=\"pic\">zhouyu</f> <f n=\"intro\">Xích Bích Nghiệp Viêm, đánh 2 dãy, được thả 2 lần, kèm buff Hỗn Loạn. Khi dưới đất có buff Cháy, sát thương tăng </f> <f n=\"troop\">33</f> <f n=\"id\">103</f></r>\n<r><f n=\"tactic_id\">1904</f> <f n=\"name\">Tào Tháo</f> <f n=\"sp_i\">Hiệu Lệnh Thiên Hạ, thêm tấm bảo vệ cho 5 dãy phe ta, khi địch tạo sát thương vượt quá giới hạn, tấm chắn sẽ bị vỡ</f> <f n=\"pic\">caocao2</f> <f n=\"intro\"></f> <f n=\"troop\">45</f> <f n=\"id\">107</f></r>\n<r><f n=\"tactic_id\">1301</f> <f n=\"name\">Lục Tốn</f> <f n=\"sp_i\">Hỏa Thêu Liên Doanh, phóng lửa lên trận địa địch, bộ đội bị cháy sẽ mất Binh Lực theo %, kéo dài 5 hiệp;</f> <f n=\"pic\">luxun</f> <f n=\"intro\">Hỏa Diệm</f> <f n=\"troop\">32</f> <f n=\"id\">110</f></r>\n<r><f n=\"tactic_id\">1601</f> <f n=\"name\">Lữ Bố</f> <f n=\"sp_i\">Mãnh Tướng Vô Song, tấn công 3 dãy địch, mỗi lần khiêu chiến được thả 1 lần chiến pháp. Sau khi chết sẽ nổ tung càn quét quân địch. Giết càng nhiều tướng, phạm vi càn quét càng rộng.</f> <f n=\"pic\">lvbu</f> <f n=\"intro\">Xích Thố Tập Kích, sau khi chết càn quét phe địch</f> <f n=\"troop\">40</f> <f n=\"id\">201</f></r>\n<r><f n=\"tactic_id\">1101</f> <f n=\"name\">Trương Phi</f> <f n=\"sp_i\">Chấn Thiên Bào Hao, tấn công 2 dãy địch, HP càng ít, uy lực chiến pháp càng cao</f> <f n=\"pic\">zhangfei</f> <f n=\"intro\">Chấn Thiên Bào Hao, sát thương chiến pháp liên quan đến HP bản thân, HP càng ít, uy lực càng cao</f> <f n=\"troop\">5</f> <f n=\"id\">202</f></r>\n<r><f n=\"tactic_id\">1102</f> <f n=\"name\">Quan Vũ</f> <f n=\"sp_i\">Võ Thần Hộ Thể, tấn công 3 dãy địch, tăng mạnh phòng ngự chiến pháp của 4 dãy phe ta</f> <f n=\"pic\">guanyu</f> <f n=\"intro\"></f> <f n=\"troop\">10</f> <f n=\"id\">203</f></r>\n<r><f n=\"tactic_id\">1401</f> <f n=\"name\">Triệu Vân</f> <f n=\"sp_i\">Long Thương, tấn công 3 dãy địch, mỗi khi giết 1 tướng địch, thả 1 lần chiến pháp</f> <f n=\"pic\">zhaoyun</f> <f n=\"intro\">Cứ giết 1 kẻ địch sẽ có thêm 1 lần thả kỹ năng</f> <f n=\"troop\">34</f> <f n=\"id\">204</f></r>\n<r><f n=\"tactic_id\">701</f> <f n=\"name\">Mã Siêu</f> <f n=\"sp_i\">Thiết Kỵ Vô Địch, tấn công 3 dãy địch, tạo sát thương cực lớn</f> <f n=\"pic\">machao</f> <f n=\"intro\"></f> <f n=\"troop\">10</f> <f n=\"id\">205</f></r>\n<r><f n=\"tactic_id\">1002</f> <f n=\"name\">Thái Sử Từ</f> <f n=\"sp_i\">Thừa Thắng Truy Kích, tấn công 4 dãy địch, được thả 2 lần</f> <f n=\"pic\">taishici</f> <f n=\"intro\">Được thả 2 lần chiến pháp</f> <f n=\"troop\">28</f> <f n=\"id\">206</f></r>\n<r><f n=\"tactic_id\">802</f> <f n=\"name\">Hứa Chử</f> <f n=\"sp_i\">Bối Thủy Chiến, tấn công 4 dãy địch, quân địch càng nhiều, uy lực càng cao</f> <f n=\"pic\">xuchu</f> <f n=\"intro\">Quân địch càng nhiều, Tấn Công và uy lực chiến pháp càng cao</f> <f n=\"troop\">5</f> <f n=\"id\">207</f></r>\n<r><f n=\"tactic_id\">801</f> <f n=\"name\">Điển Vi</f> <f n=\"sp_i\">Bão Trời Phạt, tấn công 3 dãy địch, khiến địch không thể thả chiến thuật, chiến pháp</f> <f n=\"pic\">dianwei</f> <f n=\"intro\"></f> <f n=\"troop\">5</f> <f n=\"id\">208</f></r>\n<r><f n=\"tactic_id\">202</f> <f n=\"name\">Trương Liêu</f> <f n=\"sp_i\">Xung Phong, tấn công 1 dãy địch</f> <f n=\"pic\">zhangliao</f> <f n=\"intro\"></f> <f n=\"troop\">2</f> <f n=\"id\">209</f></r>\n<r><f n=\"tactic_id\">602</f> <f n=\"name\">Tôn Sách</f> <f n=\"sp_i\">Nhập Xâm, tấn công 2 dãy địch</f> <f n=\"pic\">sunce</f> <f n=\"intro\"></f> <f n=\"troop\">4</f> <f n=\"id\">210</f></r>\n<r><f n=\"tactic_id\">901</f> <f n=\"name\">Hoàng Trung</f> <f n=\"sp_i\">Kinh Thiên Động Địa, tấn công 4 dãy địch, tạo sát thương lớn lên phe địch</f> <f n=\"pic\">huangzhong</f> <f n=\"intro\"></f> <f n=\"troop\">15</f> <f n=\"id\">211</f></r>\n<r><f n=\"tactic_id\">503</f> <f n=\"name\">Hạ Hầu Đôn</f> <f n=\"sp_i\">Phi Vũ, tấn công 4 dãy địch, uy lực khủng khiếp</f> <f n=\"pic\">xiahoudun</f> <f n=\"intro\"></f> <f n=\"troop\">14</f> <f n=\"id\">212</f></r>\n<r><f n=\"tactic_id\">501</f> <f n=\"name\">Hạ Hầu Uyên</f> <f n=\"sp_i\">Định Quân Cô Hồn, tấn công 2 dãy địch</f> <f n=\"pic\">xiahouyuan</f> <f n=\"intro\">Không thể thả ảo ảnh, tấn công ảo ảnh được thêm 20% EXP</f> <f n=\"troop\">4</f> <f n=\"id\">213</f></r>\n<r><f n=\"tactic_id\">502</f> <f n=\"name\">Từ Hoảng</f> <f n=\"sp_i\">Bối Thủy, tấn công 3 dãy địch</f> <f n=\"pic\">xuhuang</f> <f n=\"intro\">Quân địch càng nhiều, Tấn Công và uy lực chiến pháp càng cao</f> <f n=\"troop\">9</f> <f n=\"id\">214</f></r>\n<r><f n=\"tactic_id\">604</f> <f n=\"name\">Cam Ninh</f> <f n=\"sp_i\">Cố Thủ, tấn công 4 dãy địch, càng gần thủ phủ, sát thương càng cao</f> <f n=\"pic\">ganning</f> <f n=\"intro\">Càng gần thủ phủ, sát thương càng cao</f> <f n=\"troop\">14</f> <f n=\"id\">215</f></r>\n<r><f n=\"tactic_id\">403</f> <f n=\"name\">Bàng Đức</f> <f n=\"sp_i\">Đột Kích, tấn công 3 dãy địch</f> <f n=\"pic\">pangde</f> <f n=\"intro\"></f> <f n=\"troop\">8</f> <f n=\"id\">217</f></r>\n<r><f n=\"tactic_id\">902</f> <f n=\"name\">Ngụy Diên</f> <f n=\"sp_i\">Thương Lâm Tiễn Vũ, tấn công 2 dãy địch, uy lực chiến pháp cực lớn</f> <f n=\"pic\">weiyan</f> <f n=\"intro\"></f> <f n=\"troop\">20</f> <f n=\"id\">218</f></r>\n<r><f n=\"tactic_id\">603</f> <f n=\"name\">Lữ Mông</f> <f n=\"sp_i\">Nhập Xâm, tấn công 2 dãy địch, tăng mạnh uy lực chiến pháp khi đánh thành</f> <f n=\"pic\">lvmeng</f> <f n=\"intro\"></f> <f n=\"troop\">19</f> <f n=\"id\">219</f></r>\n<r><f n=\"tactic_id\">0</f> <f n=\"name\">Tôn Thượng Hương</f> <f n=\"sp_i\"></f> <f n=\"pic\">sunshangxiang</f> <f n=\"intro\"></f> <f n=\"troop\">15</f> <f n=\"id\">220</f></r>\n<r><f n=\"tactic_id\">302</f> <f n=\"name\">Trương Hợp</f> <f n=\"sp_i\">Bão Trời Phạt, tấn công 3 dãy địch, khiến địch không thể thả chiến thuật, chiến pháp</f> <f n=\"pic\">zhanghe</f> <f n=\"intro\"></f> <f n=\"troop\">12</f> <f n=\"id\">221</f></r>\n<r><f n=\"tactic_id\">303</f> <f n=\"name\">Văn Sửu</f> <f n=\"sp_i\"></f> <f n=\"pic\">wenchou</f> <f n=\"intro\"></f> <f n=\"troop\">2</f> <f n=\"id\">222</f></r>\n<r><f n=\"tactic_id\">301</f> <f n=\"name\">Nhan Lương</f> <f n=\"sp_i\">Mãnh Công, tấn công 2 dãy địch</f> <f n=\"pic\">yanliang</f> <f n=\"intro\"></f> <f n=\"troop\">7</f> <f n=\"id\">223</f></r>\n<r><f n=\"tactic_id\">0</f> <f n=\"name\">Chu Thái</f> <f n=\"sp_i\"></f> <f n=\"pic\">zhoutai</f> <f n=\"intro\">Vật Lộn, không thể thả chiến pháp, uy lực chiến thuật vô đối</f> <f n=\"troop\">26</f> <f n=\"id\">224</f></r>\n<r><f n=\"tactic_id\">0</f> <f n=\"name\">Hoa Hùng</f> <f n=\"sp_i\"></f> <f n=\"pic\">huaxiong</f> <f n=\"intro\"></f> <f n=\"troop\">17</f> <f n=\"id\">225</f></r>\n<r><f n=\"tactic_id\">0</f> <f n=\"name\">Tào Chương</f> <f n=\"sp_i\"></f> <f n=\"pic\">caozhang</f> <f n=\"intro\"></f> <f n=\"troop\">8</f> <f n=\"id\">226</f></r>\n<r><f n=\"tactic_id\">401</f> <f n=\"name\">Nghiêm Nhan</f> <f n=\"sp_i\">Nhập Xâm, tấn công 2 dãy địch</f> <f n=\"pic\">yanyan</f> <f n=\"intro\"></f> <f n=\"troop\">18</f> <f n=\"id\">227</f></r>\n<r><f n=\"tactic_id\">0</f> <f n=\"name\">Đổng Trác</f> <f n=\"sp_i\"></f> <f n=\"pic\">dongzhuo</f> <f n=\"intro\"></f> <f n=\"troop\">8</f> <f n=\"id\">228</f></r>\n<r><f n=\"tactic_id\">0</f> <f n=\"name\">Trương Nhiệm</f> <f n=\"sp_i\"></f> <f n=\"pic\">zhangren</f> <f n=\"intro\"></f> <f n=\"troop\">8</f> <f n=\"id\">229</f></r>\n<r><f n=\"tactic_id\">1501</f> <f n=\"name\">Cam Ninh</f> <f n=\"sp_i\">Tường Đồng Vách Sắt, tấn công 4 dãy địch, càng gần thủ phủ, uy lực chiến pháp càng cao</f> <f n=\"pic\">zhenganning</f> <f n=\"intro\">Càng gần thủ phủ, uy lực chiến pháp càng cao</f> <f n=\"troop\">37</f> <f n=\"id\">230</f></r>\n<r><f n=\"tactic_id\">0</f> <f n=\"name\">Quan Hưng</f> <f n=\"sp_i\"></f> <f n=\"pic\">guanxing</f>